insert into misconceptions (code, name, description, example, area_id, node_id, origin)
select v.code, v.name, v.description, v.example, a.id, n.id,
       v.origin::misconception_origin
from (values
  ($c$ENT-REC-MAGN$c$, $c$Compara negativos por su magnitud$c$, $c$Entre dos negativos elige como mayor el de mayor número "visible". Traslada el orden de los naturales a los negativos sin invertirlo: como 7 > 3, concluye que -7 > -3. Es el error central del nodo y debe aparecer como distractor en la mayoría de los ítems de comparación.$c$, $c$-7 > -3$c$, $c$NUM$c$, $c$NUM-ENT-REC$c$, $c$docente$c$),
  ($c$ENT-REC-SINSIGNO$c$, $c$Ignora el signo al comparar negativo con positivo$c$, $c$Compara un negativo con un positivo mirando solo los dígitos. Se registra separado de ENT-REC-MAGN a propósito: MAGN ocurre entre dos negativos y este cruza el cero. Un estudiante puede ordenar bien -7 < -3 y aun así decir que -8 > 5.$c$, $c$-8 > 5$c$, $c$NUM$c$, $c$NUM-ENT-REC$c$, $c$docente$c$),
  ($c$ENT-REC-CERO$c$, $c$Cree que 0 es el menor de los enteros$c$, $c$Arrastra la idea de los naturales de que el 0 es el piso: "no hay nada menos que cero". Ubica los negativos por encima del 0 o los trata como mayores que él.$c$, $c$0 < -2$c$, $c$NUM$c$, $c$NUM-ENT-REC$c$, $c$docente$c$),
  ($c$ENT-REC-SUCESOR$c$, $c$Invierte antecesor y sucesor con negativos$c$, $c$Para el sucesor de un negativo se aleja del 0 en vez de moverse a la derecha. Usa "sucesor = el número que sigue al leer" (4, 5, 6...) y lo aplica a la magnitud. Con positivos no se nota, solo aparece con negativos.$c$, $c$sucesor de -4 = -5$c$, $c$NUM$c$, $c$NUM-ENT-REC$c$, $c$docente$c$),
  ($c$ENT-REC-ESCALA$c$, $c$Lee cada marca de la recta como una unidad$c$, $c$En una recta cuya escala no es 1 (de 2 en 2, de 5 en 5), cuenta marcas en vez de leer su valor: asigna 1, 2, 3... a las marcas sucesivas aunque cada una valga más. Sin observación en aula; se mantiene porque la PAES usa rectas con escala.$c$, $c$escala de 2 en 2 desde 0: lee la 3ª marca como 3 (vale 6)$c$, $c$NUM$c$, $c$NUM-ENT-REC$c$, $c$hipotesis$c$),
  ($c$ENT-REC-CONTEO$c$, $c$Cuenta el punto de partida al medir en la recta$c$, $c$Al contar cuántas unidades hay entre dos enteros cuenta los números (incluyendo el de partida) en vez de los saltos. Da siempre una unidad de más. Es más frecuente cuando el recorrido cruza el cero.$c$, $c$de -2 a 3 cuenta 6 unidades (son 5)$c$, $c$NUM$c$, $c$NUM-ENT-REC$c$, $c$docente$c$),
  ($c$ENT-REC-CTXSIGNO$c$, $c$Asigna mal el signo en un contexto$c$, $c$Traduce mal una situación a entero: "bajo el nivel del mar", "bajo cero", "deuda" o "retroceso" quedan como positivos. Después compara bien, pero sobre números con el signo equivocado.$c$, $c$5 m bajo el nivel del mar = +5$c$, $c$NUM$c$, $c$NUM-ENT-REC$c$, $c$docente$c$),
  ($c$ENT-REC-DIRECCION$c$, $c$Invierte izquierda y derecha al moverse en la recta$c$, $c$Al desplazarse en la recta se mueve hacia el lado contrario: trata "a la izquierda" como aumentar. A diferencia de ENT-REC-SUCESOR, ocurre también con puros positivos ("3 a la izquierda de 5" = 8), y a diferencia de ENT-REC-SINSIGNO no tiene que ver con comparar sino con moverse. Con negativos y sucesor/antecesor da la misma respuesta que SUCESOR; los ítems que buscan distinguirlos usan desplazamientos, no sucesores.$c$, $c$3 unidades a la izquierda de 1 = 4$c$, $c$NUM$c$, $c$NUM-ENT-REC$c$, $c$docente$c$),
  ($c$ENT-ADI-REGLAMUL$c$, $c$Aplica la regla de signos de la multiplicación a la suma$c$, $c$Lleva "menos con menos da más" a la suma y la resta: dos negativos que se suman o un negativo al que se le resta un positivo le dan resultado positivo. Es el único error del nodo que produce un positivo a partir de dos cantidades negativas, y se vuelve más frecuente después de ver ENT-MUL.$c$, $c$-3 - 5 = 8$c$, $c$NUM$c$, $c$NUM-ENT-ADI$c$, $c$docente$c$),
  ($c$ENT-ADI-MAGNOP$c$, $c$Decide sumar o restar por el símbolo de la operación$c$, $c$Mira el símbolo de la operación y no los signos de los números: si ve "+" suma los tamaños, si ve "-" los resta, y deja el signo del negativo que aparece. Se separa de ENT-ADI-INVIERTE con -7 + 3 (MAGNOP da -10, INVIERTE da 4) y de ENT-ADI-DOBLENEG con 5 - (-3) (MAGNOP da -2, DOBLENEG da 2). En 3 - 7, sin negativos a la vista, coincide con INVIERTE: ahí se etiqueta INVIERTE. En una cadena a - b + c con a < b coincide con ENT-ADI-RESTAGRUPA: esos ítems no usan las dos.$c$, $c$-7 + 3 = -10$c$, $c$NUM$c$, $c$NUM-ENT-ADI$c$, $c$docente$c$),
  ($c$ENT-ADI-INVIERTE$c$, $c$Resta el mayor menos el menor y deja el resultado positivo$c$, $c$Arrastra de los naturales que "no se puede quitar 7 a 3": da vuelta la resta como si fuera conmutativa y el resultado queda positivo. También aparece en sumas con signos distintos, donde resta bien los tamaños pero no pone el signo del que tiene mayor tamaño.$c$, $c$3 - 7 = 4$c$, $c$NUM$c$, $c$NUM-ENT-ADI$c$, $c$docente$c$),
  ($c$ENT-ADI-DOBLENEG$c$, $c$Ignora que está restando un negativo$c$, $c$Lee a - (-b) como a - b: el signo del número que se resta desaparece y no se transforma en suma. Un estudiante con solo este error resuelve bien -7 + 3; falla únicamente cuando se resta un negativo, incluidas las diferencias en contexto que cruzan el cero (máxima 4, mínima -6: da 2).$c$, $c$5 - (-3) = 2$c$, $c$NUM$c$, $c$NUM-ENT-ADI$c$, $c$docente$c$),
  ($c$ENT-ADI-RESTAGRUPA$c$, $c$Aplica el signo menos a todo lo que viene después$c$, $c$En una cadena de sumas y restas trata el primer "-" como si encerrara el resto entre paréntesis: 10 - 3 + 2 lo calcula como 10 - (3 + 2). Solo aparece con tres o más términos. Borde con ENT-PRIOR: se queda en ADI porque la cadena es solo de sumas y restas.$c$, $c$10 - 3 + 2 = 5$c$, $c$NUM$c$, $c$NUM-ENT-ADI$c$, $c$docente$c$),
  ($c$ENT-ADI-VARORDEN$c$, $c$Calcula la variación como inicial menos final$c$, $c$Invierte el orden de la resta al calcular una variación o un cambio: hace inicial - final en vez de final - inicial. Acierta el tamaño y falla el signo, así que una subida queda como bajada. Solo aparece en ítems de variación.$c$, $c$de -3 °C a 5 °C: variación -8$c$, $c$NUM$c$, $c$NUM-ENT-ADI$c$, $c$docente$c$),
  ($c$ENT-MUL-REGLASUMA$c$, $c$Aplica la regla de signos de la suma a la multiplicación$c$, $c$Espejo de ENT-ADI-REGLAMUL: trae a la multiplicación y la división lo que sabe de la suma. Dos negativos "juntan" un negativo más grande ((−4)(−5) = −20), y con signos distintos pone el signo del factor de mayor tamaño ((−2) · 6 = 12). Es la misconception central del nodo. Se separa de MAYORIA en un producto de varios factores donde el de mayor tamaño y la mayoría tienen signos distintos, o con valor + afirmación.$c$, $c$(−4)(−5) = −20;  (−2) · 6 = 12$c$, $c$NUM$c$, $c$NUM-ENT-MUL$c$, $c$hipotesis$c$),
  ($c$ENT-MUL-MAYORIA$c$, $c$Decide el signo de un producto por mayoría$c$, $c$Con tres o más factores, le pone al resultado el signo que más se repite en vez de contar si los negativos son una cantidad par o impar: (−1) · 2 · 3 = 6 porque "hay más positivos". Solo aparece con tres o más factores. Acierta siempre que la mayoría coincide con la paridad (tres negativos solos, por ejemplo).$c$, $c$(−1) · 2 · 3 = 6$c$, $c$NUM$c$, $c$NUM-ENT-MUL$c$, $c$hipotesis$c$),
  ($c$ENT-MUL-SUMA$c$, $c$Suma los números que se multiplican$c$, $c$Lee dos paréntesis seguidos, o un número pegado a un paréntesis, como suma: (−4)(3) = −1. En situaciones que se repiten (baja 3 pisos por minuto durante 4 minutos) junta los datos sumando en vez de multiplicar. Solo se usa en ítems escritos sin punto de multiplicación o en contexto: con "·" a la vista la regla no se activa.$c$, $c$(−4)(3) = −1$c$, $c$NUM$c$, $c$NUM-ENT-MUL$c$, $c$hipotesis$c$),
  ($c$ENT-MUL-DIVCERO$c$, $c$Confunde dividir el cero con dividir por cero$c$, $c$Cree que a ÷ 0 = 0, o al revés, que 0 ÷ a no está definido. Es una sola regla mal ubicada: sabe que "con el cero hay un problema" pero no dónde. Se separa de CERONEUTRO porque solo aparece en divisiones. Se mantiene como una sola misconception porque ningún ítem de opción múltiple separa las dos direcciones sin que una de ellas coincida con la correcta.$c$, $c$(−8) ÷ 0 = 0$c$, $c$NUM$c$, $c$NUM-ENT-MUL$c$, $c$hipotesis$c$),
  ($c$ENT-MUL-CERONEUTRO$c$, $c$Trata el cero como si no cambiara el producto$c$, $c$Se salta el factor 0, como si fuera el 1: (−5) · 0 · (−2) = 10 y 9 · 0 = 9. Confunde el neutro de la multiplicación (1) con el de la suma (0). Solo aparece en productos: en divisiones con cero se etiqueta DIVCERO.$c$, $c$(−5) · 0 · (−2) = 10$c$, $c$NUM$c$, $c$NUM-ENT-MUL$c$, $c$hipotesis$c$),
  ($c$ENT-MUL-INVERSA$c$, $c$Multiplica cuando corresponde dividir$c$, $c$Usa la operación directa donde hace falta la inversa: para hallar el factor que falta (? · (−5) = −35) multiplica −35 · (−5), y al repartir una cantidad en partes iguales la multiplica por el número de partes. También al revés: reparte cuando la situación repite. Acierta el signo o no, según los números; lo que la delata es el tamaño del resultado.$c$, $c$? · (−5) = −35  →  175$c$, $c$NUM$c$, $c$NUM-ENT-MUL$c$, $c$hipotesis$c$),
  ($c$ENT-PRIOR-IZQDER$c$, $c$Calcula de izquierda a derecha sin mirar la prioridad$c$, $c$Opera en el orden en que lee: en 5 + 3 · (−2) suma primero y obtiene 8 · (−2) = −16. Trata la expresión como si cada operación encerrara entre paréntesis todo lo anterior. Es la misconception central del nodo. Solo se ve cuando una suma o resta aparece antes que una multiplicación o división.$c$, $c$5 + 3 · (−2) = −16$c$, $c$NUM$c$, $c$NUM-ENT-PRIOR$c$, $c$hipotesis$c$),
  ($c$ENT-PRIOR-MULTDIV$c$, $c$Multiplica antes de dividir$c$, $c$Lee la regla como una lista ordenada (primero multiplicar, después dividir) en vez de "multiplicación y división al mismo nivel, de izquierda a derecha": 24 ÷ 4 · 2 = 24 ÷ 8 = 3. Se separa de IZQDER porque en una cadena de solo · y ÷ IZQDER acierta. El análogo con sumas y restas es ENT-ADI-RESTAGRUPA.$c$, $c$24 ÷ 4 · 2 = 3$c$, $c$NUM$c$, $c$NUM-ENT-PRIOR$c$, $c$hipotesis$c$),
  ($c$ENT-PRIOR-SIGNOPAR$c$, $c$El menos delante del paréntesis afecta solo al primer término$c$, $c$Saca el paréntesis sin calcular adentro y el signo menos queda solo con el primer número: 10 − (4 − 9) = 10 − 4 − 9 = −3. Es la versión numérica de EXP-ADI-SIGNOPAR (álgebra); PRIOR no es ancestro de ALG-EXP-ADI, por eso son dos entradas.$c$, $c$10 − (4 − 9) = −3$c$, $c$NUM$c$, $c$NUM-ENT-PRIOR$c$, $c$hipotesis$c$),
  ($c$ENT-PRIOR-PARCIAL$c$, $c$El número de afuera multiplica solo al primer término$c$, $c$En a(b − c) multiplica a solo por b: 3(4 − 6) = 12 − 6 = 6. Deja el resto del paréntesis sin multiplicar. Se separa de ENT-MUL-SUMA (que lee a(b − c) como a + (b − c)) porque PARCIAL sí multiplica.$c$, $c$3(4 − 6) = 6$c$, $c$NUM$c$, $c$NUM-ENT-PRIOR$c$, $c$hipotesis$c$),
  ($c$ENT-PRIOR-RAYA$c$, $c$La raya de fracción divide solo el término más cercano$c$, $c$No ve la raya de fracción como agrupación: en (−12 + 4)/(−2) divide solo el 4 y obtiene −12 − 2 = −14. Aplica la prioridad de la división como si la expresión estuviera escrita en una línea sin paréntesis.$c$, $c$(−12 + 4)/(−2) = −14$c$, $c$NUM$c$, $c$NUM-ENT-PRIOR$c$, $c$hipotesis$c$),
  ($c$ENT-DIVIS-INVIERTE$c$, $c$Confunde múltiplo con divisor$c$, $c$Invierte la relación: lista múltiplos cuando le piden divisores (o al revés), dice que 24 es divisor de 6, o lee "divisible por 9" como "divisor de 9". Es la misconception central del nodo. Una señal: un "divisor" mayor que el número.$c$, $c$divisores de 6: 6, 12, 18, 24$c$, $c$NUM$c$, $c$NUM-ENT-DIVIS$c$, $c$hipotesis$c$),
  ($c$ENT-DIVIS-UNO$c$, $c$Clasifica el 1 como primo o como compuesto$c$, $c$No sabe que el 1 no es primo ni compuesto. Casi siempre lo pone entre los primos ("tiene como divisores al 1 y a sí mismo") y lo incluye en descomposiciones (1 · 2 · 3 · 5).$c$, $c$1 es primo$c$, $c$NUM$c$, $c$NUM-ENT-DIVIS$c$, $c$hipotesis$c$),
  ($c$ENT-DIVIS-IMPARPRIMO$c$, $c$Confunde primo con impar$c$, $c$Usa "impar" como si fuera "primo": 21, 27 o 35 le parecen primos, y el 2 no, porque es par. Se separa de ULTCIFRA con un primo que termina en 3 (IMPARPRIMO acierta) y con el 2.$c$, $c$21 es primo; 2 no es primo$c$, $c$NUM$c$, $c$NUM-ENT-DIVIS$c$, $c$hipotesis$c$),
  ($c$ENT-DIVIS-ULTCIFRA$c$, $c$Aplica al 3 y al 9 un criterio de última cifra$c$, $c$Generaliza el criterio del 2, del 5 y del 10 (mirar la última cifra) a divisores que no lo tienen: 43 es divisible por 3 porque termina en 3; 139 por 9 porque termina en 9; 87 no es divisible por 3 porque termina en 7. También cuenta "los múltiplos de 7" como los que terminan en 7.$c$, $c$43 es divisible por 3$c$, $c$NUM$c$, $c$NUM-ENT-DIVIS$c$, $c$hipotesis$c$),
  ($c$ENT-DIVIS-CRITERIO$c$, $c$Usa el criterio de un divisor más chico como suficiente$c$, $c$Comprueba solo una parte: divisible por 3 le basta para el 9, ser par le basta para el 4 o para el 6, y "par y divisible por 3" le basta para el 18. Conoce los criterios; lo que falla es qué divisor certifica cada uno.$c$, $c$57 es divisible por 9 (5 + 7 = 12)$c$, $c$NUM$c$, $c$NUM-ENT-DIVIS$c$, $c$hipotesis$c$),
  ($c$ENT-DIVIS-EXTREMOS$c$, $c$Deja fuera el 1 y el propio número$c$, $c$Al listar o contar divisores omite el 1 y el número mismo ("esos no cuentan"), y a veces cree que un número no es múltiplo de sí mismo. Divisores de 20: 2, 4, 5, 10. Se separa de SOLOPRIMOS porque sí incluye los divisores compuestos.$c$, $c$divisores de 20: 2, 4, 5, 10$c$, $c$NUM$c$, $c$NUM-ENT-DIVIS$c$, $c$hipotesis$c$),
  ($c$ENT-DIVIS-SOLOPRIMOS$c$, $c$Cree que los divisores de un número son sus factores primos$c$, $c$Confunde "divisores" con "factores primos": los divisores de 20 son 2 y 5; 6 no divide a 90 porque no es primo. Al descomponer escribe cada primo una sola vez (60 = 2 · 3 · 5).$c$, $c$divisores de 20: 2 y 5$c$, $c$NUM$c$, $c$NUM-ENT-DIVIS$c$, $c$hipotesis$c$),
  ($c$ENT-DIVIS-COMPUESTO$c$, $c$Deja factores compuestos en la descomposición$c$, $c$Se detiene en un producto correcto pero con factores que no son primos: 60 = 4 · 15, 126 = 2 · 9 · 7. Sabe que hay que "partir" el número, no que la descomposición termina cuando todos los factores son primos.$c$, $c$60 = 4 · 15$c$, $c$NUM$c$, $c$NUM-ENT-DIVIS$c$, $c$hipotesis$c$),
  ($c$ENT-MCM-CAMBIA$c$, $c$Intercambia mcm y MCD$c$, $c$Da el MCD cuando le piden el mcm (o al revés), o en un problema usa el que no corresponde: para saber cuándo coinciden dos buses usa el MCD. Es la misconception central del nodo. La delata el tamaño: un mcm menor que los números o un MCD mayor.$c$, $c$mcm(8, 12) = 4$c$, $c$NUM$c$, $c$NUM-ENT-MCM$c$, $c$hipotesis$c$),
  ($c$ENT-MCM-PRODUCTO$c$, $c$Cree que el mcm es el producto de los números$c$, $c$Multiplica los números: mcm(8, 12) = 96. El producto siempre es múltiplo común, por eso la regla "funciona" con primos entre sí y se refuerza. Por descomposición aparece como juntar todos los factores de los dos sin quitar los repetidos.$c$, $c$mcm(8, 12) = 96$c$, $c$NUM$c$, $c$NUM-ENT-MCM$c$, $c$hipotesis$c$),
  ($c$ENT-MCM-SUMA$c$, $c$Suma los períodos para saber cuándo coinciden$c$, $c$En problemas de cosas que se repiten, suma los períodos: buses cada 6 y cada 10 minutos coinciden a los 16. Trata "juntar dos ciclos" como juntar dos cantidades. Solo aparece en contexto o con números pequeños.$c$, $c$cada 6 y cada 10 minutos: coinciden a los 16$c$, $c$NUM$c$, $c$NUM-ENT-MCM$c$, $c$hipotesis$c$),
  ($c$ENT-MCM-MAYOR$c$, $c$Toma el mayor como mcm o el menor como MCD$c$, $c$Da como mcm el mayor de los números y como MCD el menor, sin comprobar que uno sea múltiplo o divisor del otro. Acierta cuando uno divide al otro (mcm(4, 12) = 12), y por eso se sostiene.$c$, $c$mcm(6, 10) = 10$c$, $c$NUM$c$, $c$NUM-ENT-MCM$c$, $c$hipotesis$c$),
  ($c$ENT-MCM-SOLOCOMUN$c$, $c$Para el mcm usa solo los factores comunes$c$, $c$Mezcla las dos reglas de la descomposición: para el mcm toma los factores comunes (con su mayor repetición) y deja fuera los que no comparten. 8 = 2 · 2 · 2 y 12 = 2 · 2 · 3 dan 8. Solo se ve por descomposición o con números que la vuelven distinta del mcm y del MCD.$c$, $c$mcm(8, 12) = 8$c$, $c$NUM$c$, $c$NUM-ENT-MCM$c$, $c$hipotesis$c$),
  ($c$ENT-MCM-PRIMERCOMUN$c$, $c$Da como MCD el primer divisor común que encuentra$c$, $c$Lee "común divisor" y se detiene en el primero mayor que 1 (casi siempre 2 o 3), sin buscar el mayor: MCD(12, 18) = 2. Por descomposición aparece como elegir un solo factor común en vez de multiplicarlos todos. Es el espejo de lo que en el mcm sí funciona (el primer múltiplo común es el mínimo).$c$, $c$MCD(12, 18) = 2$c$, $c$NUM$c$, $c$NUM-ENT-MCM$c$, $c$hipotesis$c$),
  ($c$ENT-ABS-CAMBIA$c$, $c$Cree que el valor absoluto cambia el signo$c$, $c$Generaliza el ejemplo |-3| = 3 como "el valor absoluto le cambia el signo al número" y lo aplica también a los positivos: |5| = -5. Con negativos acierta, así que solo se ve con positivos. En |x| = a se queda con x = -a. Se separa de ENT-ABS-PARENT con |5| (CAMBIA da -5, PARENT da 5).$c$, $c$|5| = -5$c$, $c$NUM$c$, $c$NUM-ENT-ABS$c$, $c$docente$c$),
  ($c$ENT-ABS-PARENT$c$, $c$Lee las barras como si fueran paréntesis$c$, $c$Las barras no le hacen nada al número: |-5| = -5. Al comparar valores absolutos compara los números mismos (|-8| < |5| porque -8 < 5), y en |x| <= a acepta todos los enteros menores o iguales que a. Con positivos acierta, así que solo se ve con negativos.$c$, $c$|-5| = -5$c$, $c$NUM$c$, $c$NUM-ENT-ABS$c$, $c$docente$c$),
  ($c$ENT-ABS-SIGNOFUERA$c$, $c$Cree que las barras también borran el signo de afuera$c$, $c$Aprende que "el valor absoluto siempre es positivo" y lo extiende al signo menos que está fuera de las barras: -|-6| = 6 y -|4| = 4. Se separa de ENT-ABS-CAMBIA y ENT-ABS-PARENT con -|4|: las dos dan -4 y SIGNOFUERA da 4.$c$, $c$-|-6| = 6$c$, $c$NUM$c$, $c$NUM-ENT-ABS$c$, $c$docente$c$),
  ($c$ENT-ABS-UNASOL$c$, $c$Considera solo el lado positivo del 0$c$, $c$Lee |x| como "el número sin signo" y al devolverse se queda solo con los no negativos: |x| = 5 tiene solo la solución 5, y los enteros con |x| <= 3 son 0, 1, 2 y 3. Olvida que a la misma distancia del 0 hay un número a cada lado. Coincide con ENT-ABS-PARENT en |x| = a con a > 0; se separa en |x| <= a (PARENT acepta infinitos).$c$, $c$|x| = 5  =>  x = 5$c$, $c$NUM$c$, $c$NUM-ENT-ABS$c$, $c$docente$c$),
  ($c$ENT-ABS-NEGSOL$c$, $c$Busca números cuyo valor absoluto sea negativo$c$, $c$Busca los números que cumplen |x| = -4 igual que si fuera |x| = 4 y responde 4 y -4, sin notar que una distancia no puede ser negativa. Solo se ve cuando el valor absoluto se iguala o se compara con un negativo; con a > 0 no falla.$c$, $c$|x| = -4  =>  x = 4 o x = -4$c$, $c$NUM$c$, $c$NUM-ENT-ABS$c$, $c$docente$c$),
  ($c$ENT-ABS-DISTTAM$c$, $c$Calcula la distancia restando las distancias al 0$c$, $c$Para la distancia entre dos enteros resta sus valores absolutos, sin mirar si están al mismo lado del 0. Acierta cuando están al mismo lado (-3 y -8: 5) y falla cuando el 0 queda entre ellos (-3 y 5: da 2, son 8). En el cálculo 5 - (-3) coincide con ENT-ADI-DOBLENEG: los ítems de este nodo no escriben esa resta.$c$, $c$distancia entre -3 y 5 = 2$c$, $c$NUM$c$, $c$NUM-ENT-ABS$c$, $c$docente$c$),
  ($c$ENT-ABS-SALTOS$c$, $c$Cuenta la distancia en vez de los enteros$c$, $c$Para contar los enteros con |x| <= a mide cuánto hay del menor al mayor (2a) en vez de contar los números (2a + 1): pierde uno, que suele ser el 0. Es el error inverso de ENT-REC-CONTEO, que cuenta números cuando debería contar saltos. Solo aparece en ítems de conteo.$c$, $c$enteros con |x| <= 3: cuenta 6 (son 7)$c$, $c$NUM$c$, $c$NUM-ENT-ABS$c$, $c$docente$c$),
  ($c$ENT-ABS-DISTRIB$c$, $c$Saca el valor absoluto de cada término por separado$c$, $c$Trata las barras como un factor que se reparte: |a - b| lo calcula como |a| - |b| y |a + b| como |a| + |b|, conservando la operación de adentro. Puede dar un resultado negativo (|3 - 8| = -5) o uno demasiado grande (|-9 + 2| = 11). Se separa de ENT-ABS-PARENT con |-2 - 6| (DISTRIB da -4, PARENT da -8) y de ENT-ABS-QUITASIGNO con |3 - 8| (DISTRIB da -5, QUITASIGNO da 11).$c$, $c$|3 - 8| = |3| - |8| = -5$c$, $c$NUM$c$, $c$NUM-ENT-ABS$c$, $c$docente$c$),
  ($c$ENT-ABS-QUITASIGNO$c$, $c$Borra todos los signos de adentro y suma$c$, $c$Lee "el valor absoluto deja todo positivo" como "borra todos los signos menos que hay adentro", incluido el de la operación: |3 - 8| queda 3 + 8 = 11 y |b - a| queda b + a. Acierta cuando los dos términos ya se alejaban del 0 hacia el mismo lado (|-2 - 6| = 8), así que solo se ve cuando adentro hay una resta que acerca al 0.$c$, $c$|3 - 8| = 3 + 8 = 11$c$, $c$NUM$c$, $c$NUM-ENT-ABS$c$, $c$docente$c$)
) as v(code, name, description, example, area_code, node_code, origin)
left join areas a on a.code = v.area_code
join nodes n      on n.code = v.node_code
on conflict (code) do update
  set name        = excluded.name,
      description = excluded.description,
      example     = excluded.example,
      node_id     = excluded.node_id,
      origin      = excluded.origin;

